// AI-powered workflow analysis using MCP approach
const items = $input.all();
const workflowAnalysis = [];

for (const item of items) {
  if (item.json && item.json.data) {
    for (const workflow of item.json.data) {
      const workflowJson = JSON.stringify(workflow);

      // AI analysis of workflow health
      const analysis = {
        id: workflow.id,
        name: workflow.name,
        hasAIExpressions: workflowJson.includes('$fromAI'),
        hasMCPFeatures: workflowJson.includes('mcp') || workflowJson.includes('MCP'),
        isAgentic: workflowJson.includes('agent') || workflowJson.includes('Agent'),
        healthScore: 0,
        recommendations: []
      };

      // Calculate health score
      if (analysis.hasAIExpressions) {
        analysis.healthScore -= 30;
        analysis.recommendations.push('Replace $fromAI with MCP Client Tool nodes');
      }

      if (analysis.hasMCPFeatures) {
        analysis.healthScore += 20;
        analysis.recommendations.push('Already has MCP integration');
      }

      if (analysis.isAgentic) {
        analysis.healthScore += 15;
        analysis.recommendations.push('Agentic workflow detected');
      }

      // Base score
      analysis.healthScore += 50;

      workflowAnalysis.push(analysis);
    }
  }
}

// Sort by health score (worst first)
workflowAnalysis.sort((a, b) => a.healthScore - b.healthScore);

return workflowAnalysis.map(workflow => ({ json: workflow }));

// AI-powered workflow transformation using MCP approach
const workflow = $input.first().json;
const originalWorkflow = $('🔍 Filter Workflows Needing Fixes').item.json;

// Create MCP-powered version
const mcpWorkflow = {
  name: `${workflow.name} - MCP Enhanced`,
  nodes: [],
  connections: {},
  settings: workflow.settings || { executionOrder: 'v1' },
  staticData: workflow.staticData
};

// Transform nodes to use MCP tools
if (workflow.nodes) {
  mcpWorkflow.nodes = workflow.nodes.map(node => {
    const transformedNode = { ...node };

    // Replace AI expressions with MCP Client Tool nodes
    if (node.parameters) {
      const paramsStr = JSON.stringify(node.parameters);
      if (paramsStr.includes('$fromAI')) {
        // Transform to MCP Client Tool
        transformedNode.type = 'n8n-nodes-base.mcpClientTool';
        transformedNode.parameters = {
          toolName: 'workflow_fixer',
          input: '{{ $json.default_value }}',
          options: {}
        };

        // Add MCP-specific configuration
        transformedNode.parameters.mcpServer = 'n8n-mcp';
        transformedNode.parameters.toolDescription = 'AI-powered workflow parameter generator';
      }
    }

    return transformedNode;
  });
}

// Add MCP Client Tool nodes for AI functionality
const mcpNodes = [
  {
    id: 'mcp-ai-analyzer',
    name: '🤖 MCP AI Analyzer',
    type: 'n8n-nodes-base.mcpClientTool',
    typeVersion: 1,
    position: [0, 0],
    parameters: {
      toolName: 'workflow_analyzer',
      input: '{{ $json }}',
      options: {}
    }
  },
  {
    id: 'mcp-workflow-fixer',
    name: '🔧 MCP Workflow Fixer',
    type: 'n8n-nodes-base.mcpClientTool',
    typeVersion: 1,
    position: [200, 0],
    parameters: {
      toolName: 'workflow_fixer',
      input: '{{ $json }}',
      options: {}
    }
  }
];

mcpWorkflow.nodes = [...mcpNodes, ...mcpWorkflow.nodes];

// Update connections
mcpWorkflow.connections = {
  '🤖 MCP AI Analyzer': {
    main: [[{ node: '🔧 MCP Workflow Fixer', type: 'main', index: 0 }]]
  },
  '🔧 MCP Workflow Fixer': {
    main: [[{ node: '📤 Import Fixed Workflow', type: 'main', index: 0 }]]
  }
};

return [{ json: mcpWorkflow }];

// AI-powered result analysis
const importResult = $input.first().json;
const originalWorkflow = $('🔍 Filter Workflows Needing Fixes').item.json;

const result = {
  status: importResult.id ? 'success' : 'error',
  message: importResult.id ? 
    `✅ Successfully created MCP-powered workflow: ${originalWorkflow.name}` : 
    `❌ Failed to create MCP workflow: ${originalWorkflow.name}`,
  newId: importResult.id || null,
  originalId: originalWorkflow.id,
  workflowName: originalWorkflow.name,
  transformation: 'AI-powered MCP transformation',
  recommendations: originalWorkflow.recommendations,
  nextSteps: [
    'Configure MCP Client Tool credentials',
    'Test AI agent functionality',
    'Validate MCP tool integration'
  ]
};

return [{ json: result }];
